module ApiExceptionHandler
  extend ActiveSupport::Concern

  included do
    rescue_from ActionController::ParameterMissing, with: :render_missing_param_error
    rescue_from ActiveRecord::RecordNotFound, with: :render_record_not_found_error
    rescue_from StandardError, with: :render_unhandled_error
  end

  private
    def render_missing_param_error(exception)
      render json: {
        message: "Missing parameter(s).",
        data: {
          exception.param => [ "can't be blank" ]
        }
      }, status: :bad_request
    end

    def render_record_not_found_error(e)
      render json: { error: e.message }, status: :unprocessable_entity
    end

    def render_unhandled_error(e)
      Rails.logger.error "Unhandled error: #{e.class} - #{e.message}"
      Rails.logger.error e.backtrace.join("\n")

      render json: {
        message: "an unexpected error occurred"
      }, status: :internal_server_error
    end
end

